#include <chrono>
#include <cstdint>
#include <deque>
#include <fstream>
#include <iomanip>
#include <iostream>
#include <poll.h>
#include <sstream>
#include <string>
#include "bike/lighting_diagnostics.hpp"
#include "bike/node.hpp"
#include "bike/security.hpp"
#include "bike/supervisor.hpp"
#include "posix_serial_transport.hpp"
namespace {
struct Event{std::uint32_t time_ms;bike::NodeAddress source;bike::MessageType type;std::string text;};std::deque<Event> history;constexpr std::size_t kHistoryLimit=250;std::ofstream logfile;bool monitor=true;bool filter_node_enabled=false;bike::NodeAddress filter_node=bike::NodeAddress::Broadcast;
struct Probe{bool active{false};bike::NodeAddress target{bike::NodeAddress::Broadcast};std::uint32_t started{0};};Probe probe;
std::uint32_t now_ms(){using namespace std::chrono;return static_cast<std::uint32_t>(duration_cast<milliseconds>(steady_clock::now().time_since_epoch()).count());}
const char* node_name(bike::NodeAddress a){switch(a){case bike::NodeAddress::MainComputer:return"MAIN";case bike::NodeAddress::DiagnosticComputer:return"DIAG";case bike::NodeAddress::Northbridge:return"NORTHBRIDGE";case bike::NodeAddress::Lighting:return"LIGHTING";case bike::NodeAddress::Security:return"SECURITY";case bike::NodeAddress::Broadcast:return"BROADCAST";}return"UNKNOWN";}
const char* type_name(bike::MessageType t){switch(t){case bike::MessageType::Heartbeat:return"HEARTBEAT";case bike::MessageType::Ack:return"ACK";case bike::MessageType::Nack:return"NACK";case bike::MessageType::GetState:return"GET_STATE";case bike::MessageType::StateUpdate:return"STATE_UPDATE";case bike::MessageType::SetOutput:return"SET_OUTPUT";case bike::MessageType::InputEvent:return"INPUT_EVENT";case bike::MessageType::LightingDiagnostic:return"LIGHTING_DIAGNOSTIC";case bike::MessageType::ConfigRead:return"CONFIG_READ";case bike::MessageType::ConfigWrite:return"CONFIG_WRITE";case bike::MessageType::Fault:return"FAULT";case bike::MessageType::FaultClear:return"FAULT_CLEAR";case bike::MessageType::DeviceInfo:return"DEVICE_INFO";case bike::MessageType::DeviceDiscovery:return"DEVICE_DISCOVERY";case bike::MessageType::Diagnostic:return"DIAGNOSTIC";case bike::MessageType::SecurityCommand:return"SECURITY_COMMAND";case bike::MessageType::SecurityState:return"SECURITY_STATE";case bike::MessageType::SecurityEvent:return"SECURITY_EVENT";case bike::MessageType::AuthRequest:return"AUTH_REQUEST";case bike::MessageType::AuthResult:return"AUTH_RESULT";case bike::MessageType::FobPresent:return"FOB_PRESENT";}return"UNKNOWN";}
const char* security_event(std::uint8_t e){switch(static_cast<bike::SecurityEventCode>(e)){case bike::SecurityEventCode::ShockWarning:return"SHOCK_WARNING";case bike::SecurityEventCode::ShockTrigger:return"SHOCK_TRIGGER";case bike::SecurityEventCode::AlarmStarted:return"ALARM_STARTED";case bike::SecurityEventCode::AlarmStopped:return"ALARM_STOPPED";case bike::SecurityEventCode::Locked:return"LOCKED";case bike::SecurityEventCode::Unlocked:return"UNLOCKED";case bike::SecurityEventCode::LockPending:return"LOCK_PENDING";}return"UNKNOWN_SECURITY_EVENT";}
const char* light_status(std::uint8_t s){switch(static_cast<bike::LightingElectricalStatus>(s)){case bike::LightingElectricalStatus::Unknown:return"UNKNOWN";case bike::LightingElectricalStatus::Off:return"OFF";case bike::LightingElectricalStatus::Ok:return"OK";case bike::LightingElectricalStatus::OpenLoad:return"OPEN_LOAD";case bike::LightingElectricalStatus::OverCurrent:return"OVER_CURRENT";}return"UNKNOWN";}
const char* light_output(std::uint8_t o){switch(o){case 0:return"LEFT_INDICATOR";case 1:return"RIGHT_INDICATOR";case 2:return"BRAKE_BRIGHT";case 3:return"HIGH_BEAM";}return"UNKNOWN_OUTPUT";}
const char* health(bike::NodeHealth h){switch(h){case bike::NodeHealth::Unknown:return"UNKNOWN";case bike::NodeHealth::Online:return"ONLINE";case bike::NodeHealth::Degraded:return"DEGRADED";case bike::NodeHealth::Offline:return"OFFLINE";case bike::NodeHealth::Incompatible:return"INCOMPATIBLE";}return"?";}
std::uint32_t u32(const std::uint8_t*p){return(std::uint32_t(p[0])<<24)|(std::uint32_t(p[1])<<16)|(std::uint32_t(p[2])<<8)|p[3];}
std::string hex_payload(const bike::Packet&p){std::ostringstream o;for(std::uint16_t i=0;i<p.length;++i){if(i)o<<' ';o<<std::hex<<std::setw(2)<<std::setfill('0')<<unsigned(p.payload[i]);}return o.str();}
std::string decode(const bike::Packet&p){std::ostringstream o;o<<type_name(p.type);if(p.type==bike::MessageType::SecurityEvent&&p.length)o<<" event="<<security_event(p.payload[0]);else if(p.type==bike::MessageType::SecurityState&&p.length>=6)o<<" mode="<<unsigned(p.payload[0])<<" inhibit="<<unsigned(p.payload[1])<<" alarm="<<unsigned(p.payload[2])<<" warning="<<unsigned(p.payload[3])<<" trigger="<<unsigned(p.payload[4])<<" engine="<<unsigned(p.payload[5]);else if(p.type==bike::MessageType::StateUpdate&&p.length>=8){for(int i=0;i<4;++i)o<<' '<<light_output(p.payload[i*2])<<'='<<unsigned(p.payload[i*2+1]);}else if(p.type==bike::MessageType::LightingDiagnostic&&p.length>=24){for(int i=0;i<4;++i){int x=i*6;std::uint16_t ma=(std::uint16_t(p.payload[x+4])<<8)|p.payload[x+5];o<<" ["<<light_output(p.payload[x])<<' '<<light_status(p.payload[x+3])<<' '<<ma<<"mA]";}}else if(p.type==bike::MessageType::Diagnostic&&p.source==bike::NodeAddress::Northbridge&&p.length>=18)o<<" ports="<<unsigned(p.payload[1])<<" forwarded="<<u32(&p.payload[2])<<" dropped="<<u32(&p.payload[6])<<" route-movements="<<u32(&p.payload[10])<<" topology-faults="<<u32(&p.payload[14]);else if(p.type==bike::MessageType::Fault&&p.source==bike::NodeAddress::Northbridge&&p.length>=5)o<<" TOPOLOGY_FAULT node=0x"<<std::hex<<unsigned(p.payload[2])<<std::dec<<" expected-port="<<unsigned(p.payload[3])<<" actual-port="<<unsigned(p.payload[4]);else if(p.length)o<<" payload=["<<hex_payload(p)<<']';return o.str();}
void remember(std::uint32_t t,const bike::Packet&p,const std::string&s){history.push_back({t,p.source,p.type,s});while(history.size()>kHistoryLimit)history.pop_front();if(logfile){logfile<<t<<','<<node_name(p.source)<<','<<node_name(p.destination)<<','<<type_name(p.type)<<",\""<<s<<"\"\n";logfile.flush();}}
bool send_request(bike::BikeNode&n,bike::NodeAddress dst,bike::MessageType type,std::uint32_t now){bike::Packet p{};p.destination=dst;p.type=type;return n.send(p,now,false);}
void ping(bike::BikeNode&n,bike::NodeAddress dst,std::uint32_t now){if(send_request(n,dst,bike::MessageType::Heartbeat,now)){probe={true,dst,now};std::cout<<"PING "<<node_name(dst)<<" sent\n";}}
void selftest(bike::BikeNode&n,const bike::NetworkSupervisor&s,std::uint32_t now){std::cout<<"SELF-TEST\n";for(auto a:{bike::NodeAddress::Northbridge,bike::NodeAddress::Lighting,bike::NodeAddress::Security}){const auto*st=s.status(a);std::cout<<"  "<<node_name(a)<<": ";if(!st||!st->online){std::cout<<"FAIL offline\n";continue;}if(st->health==bike::NodeHealth::Incompatible){std::cout<<"FAIL protocol-incompatible\n";continue;}std::cout<<(st->health==bike::NodeHealth::Degraded?"WARN degraded":"PASS online")<<'\n';send_request(n,a,a==bike::NodeAddress::Northbridge?bike::MessageType::Diagnostic:bike::MessageType::GetState,now);}}
bool parse_node(const std::string&s,bike::NodeAddress&a){if(s=="northbridge")a=bike::NodeAddress::Northbridge;else if(s=="lighting")a=bike::NodeAddress::Lighting;else if(s=="security")a=bike::NodeAddress::Security;else return false;return true;}
void inventory(const bike::NetworkSupervisor&s){for(const auto&n:s.nodes())if(n.discovered)std::cout<<node_name(n.address)<<" health="<<health(n.health)<<" faults="<<n.fault_count<<" reboots="<<n.reboot_count<<'\n';}
void events(bool faults){for(const auto&e:history){if(faults&&e.type!=bike::MessageType::Fault&&e.type!=bike::MessageType::FaultClear&&e.type!=bike::MessageType::LightingDiagnostic)continue;if(filter_node_enabled&&e.source!=filter_node)continue;std::cout<<'['<<e.time_ms<<"] "<<node_name(e.source)<<' '<<e.text<<'\n';}}
}
int main(int argc,char**argv){std::string dev=argc>1?argv[1]:"/dev/serial0";PosixSerialTransport transport;if(!transport.open_device(dev,115200)){std::cerr<<"Unable to open "<<dev<<'\n';return 1;}logfile.open("motorcycle-diagnostics.csv",std::ios::app);bike::BikeNode node(bike::NodeAddress::DiagnosticComputer,transport);bike::NetworkSupervisor supervisor(node);supervisor.send_discovery(now_ms());std::cout<<"Motorcycle diagnostics on "<<dev<<"\nCommands: scan, inventory, state lighting|security, diag northbridge, ping <node>, selftest, monitor on|off, events, faults, filter <node>|off, clear, quit\n> "<<std::flush;pollfd input{0,POLLIN,0};std::string line;bool running=true;while(running){auto now=now_ms();bike::Packet p{};while(node.poll(p,now)){supervisor.observe(p,now);auto text=decode(p);remember(now,p,text);if(probe.active&&p.source==probe.target&&p.type==bike::MessageType::Heartbeat){std::cout<<"PING "<<node_name(probe.target)<<" reply "<<std::uint32_t(now-probe.started)<<"ms\n";probe.active=false;}if(monitor&&(!filter_node_enabled||p.source==filter_node||p.destination==filter_node))std::cout<<'['<<now<<"] "<<node_name(p.source)<<" -> "<<node_name(p.destination)<<' '<<text<<'\n';}if(probe.active&&std::uint32_t(now-probe.started)>1000){std::cout<<"PING "<<node_name(probe.target)<<" TIMEOUT\n";probe.active=false;}supervisor.service(now);node.service(now);int ready=::poll(&input,1,10);if(ready>0&&(input.revents&POLLIN)){if(!std::getline(std::cin,line))break;if(line=="quit"||line=="exit")running=false;else if(line=="scan")supervisor.send_discovery(now);else if(line=="inventory")inventory(supervisor);else if(line=="selftest")selftest(node,supervisor,now);else if(line=="monitor on")monitor=true;else if(line=="monitor off")monitor=false;else if(line=="events")events(false);else if(line=="faults")events(true);else if(line=="clear")history.clear();else if(line=="diag northbridge")send_request(node,bike::NodeAddress::Northbridge,bike::MessageType::Diagnostic,now);else if(line=="state lighting")send_request(node,bike::NodeAddress::Lighting,bike::MessageType::GetState,now);else if(line=="state security")send_request(node,bike::NodeAddress::Security,bike::MessageType::GetState,now);else if(line.rfind("ping ",0)==0){bike::NodeAddress a;if(parse_node(line.substr(5),a))ping(node,a,now);else std::cout<<"Unknown node\n";}else if(line.rfind("filter ",0)==0){std::string f=line.substr(7);if(f=="off")filter_node_enabled=false;else{bike::NodeAddress a;if(parse_node(f,a)){filter_node=a;filter_node_enabled=true;}else std::cout<<"Unknown filter\n";}}else if(!line.empty())std::cout<<"Unknown command\n";if(running)std::cout<<"> "<<std::flush;}}return 0;}
